        long delay = (Long) args[1];
        TimeUnit unit = (TimeUnit) args[2];
        MockScheduledFuture<Void> future = new MockScheduledFuture<Void>(command, delay, unit);
        scheduledDestroyTasks.add(future);
        return future;
    });
